const m = $input.first().json.message || {};
if (String(m.chat && m.chat.id) !== 'TELEGRAM_CHAT_ID') return [];
const t = (m.text || '').trim().toLowerCase();
if (t.startsWith('/durdur')) return [{ json: { sql: "UPDATE ayarlar SET deger = 'hayir' WHERE anahtar = 'sistem_aktif' RETURNING deger;", komut: 'durdur' } }];
if (t.startsWith('/baslat')) return [{ json: { sql: "UPDATE ayarlar SET deger = 'evet' WHERE anahtar = 'sistem_aktif' RETURNING deger;", komut: 'baslat' } }];
if (t.startsWith('/durum')) return [{ json: { sql: "SELECT to_char(zaman AT TIME ZONE 'Europe/Istanbul', 'DD.MM HH24:MI') AS saat, ajan, left(coalesce(sonuc, ''), 120) AS ozet FROM ajan_islem_kaydi ORDER BY id DESC LIMIT 10;", komut: 'durum' } }];
return [{ json: { sql: 'SELECT 1 AS bos;', komut: 'yardim' } }];

const komut = $('Komut Çöz').first().json.komut;
const satirlar = $input.all().map(i => i.json);
let metin;
if (komut === 'durdur') metin = '⏸️ Tüm otomasyon durduruldu. Yeniden başlatmak için /baslat yaz.';
else if (komut === 'baslat') metin = '▶️ Otomasyon yeniden çalışıyor.';
else if (komut === 'durum') metin = '📋 Son 10 işlem:\n' + satirlar.filter(s => s.ajan).map(s => `${s.saat} · ${s.ajan}: ${s.ozet}`).join('\n');
else metin = 'Komutlar: /durum (son işlemler), /durdur (acil durdur), /baslat (yeniden başlat). Bunları kullanmak zorunda değilsin; sistem kendi kendine çalışır.';
return [{ json: { metin } }];
